/** Single browser-facing entry point for the Phase 1 content layer. */

import { phase1Places, phase1PlaceById, PHASE1_PLACE_SOURCES } from "./places.js";
import { phase1Poems, phase1PoemById, PHASE1_POEM_RETRIEVED_AT } from "./poems.js?v=interpretation-1";

export const PHASE1_CONTENT_SCHEMA_VERSION = 2;
export const PHASE1_CONTENT_RETRIEVED_AT = PHASE1_POEM_RETRIEVED_AT;

// The catalog is generated by scripts/build-phase1-catalog.mjs.  Keeping this
// browser module independent of Node's JSON imports makes the curated ten
// poems usable directly by the app even before a build has been run.
export { phase1Places, phase1PlaceById, PHASE1_PLACE_SOURCES };
export { phase1Poems, phase1PoemById };

export const phase1CatalogMeta = {
  schemaVersion: PHASE1_CONTENT_SCHEMA_VERSION,
  generatedAt: PHASE1_CONTENT_RETRIEVED_AT,
  sourceManifest: {
    completePoems: "content/phase1/poems.js",
    places: "content/phase1/places.js",
    candidateSnapshot: "content/catalog/raw-candidates.json",
    curation: "content/catalog/curated-selection.js",
    build: "scripts/build-phase1-catalog.mjs",
  },
};

// Runtime candidate records are loaded from phase1-runtime.json by Node tools.
// The fallback list preserves the ten approved units for a static browser
// session and is replaced by the generated catalog in integrations.
export const phase1Catalog = phase1Poems.map((poem) => ({
    id: poem.id,
    title: poem.title.text,
    author: poem.author.name,
    dynasty: poem.dynasty,
    genre: poem.genre,
    text: poem.text,
    placeCandidates: [poem.placeId],
    placeRelationTypes: poem.placeRelations.map((relation) => relation.type),
    themes: [poem.spatialLearning.coreRelation],
    ageRange: [7, 12],
    scores: {
      length: 1,
      languageClarity: 1,
      imageClarity: 1,
      placeClarity: 1,
      textbookFamiliarity: 1,
      spatialLearningValue: 1,
      culturalRepresentation: 1,
    },
    textbookCommon: "curated",
    sourceSnapshot: { sourceId: "phase1-complete-unit", collection: "project-curated" },
    curation: { status: "approved_full_experience" },
    priority: "p0",
}));

export const phase1Content = {
  schemaVersion: PHASE1_CONTENT_SCHEMA_VERSION,
  retrievedAt: PHASE1_CONTENT_RETRIEVED_AT,
  places: phase1Places,
  poems: phase1Poems,
  catalog: phase1Catalog,
};

export default phase1Content;
